function normalise(text) {
  return String(text || '')
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Match a phrase selected in the HPI against the workflow index.
 * Pure text matching — no patient data, no inference.
 */
export function findWorkflowsForText(selection) {
  const q = normalise(selection);
  if (!q) return [];
  const qWords = {};
  q.split(' ').forEach(function (t) { qWords[t] = true; });
  const hits = [];
  WORKFLOWS.forEach(function (w) {
    let best = 0;
    [w.condition].concat(w.synonyms || []).forEach(function (name) {
      const n = normalise(name);
      if (!n) return;
      if (q === n) best = Math.max(best, 4);
      else if (q.indexOf(n) !== -1) best = Math.max(best, 3);
      else if (n.indexOf(q) !== -1 && q.length >= 4) best = Math.max(best, 1);
      else {
        const parts = n.split(' ').filter(function (p) { return p.length >= 3; });
        if (parts.length && parts.every(function (p) { return qWords[p]; })) best = Math.max(best, 2);
      }
    });
    if (best > 0) hits.push({ workflow: w, score: best });
  });
  return hits
    .sort(function (a, b) { return b.score - a.score || a.workflow.condition.localeCompare(b.workflow.condition); })
    .map(function (h) { return h.workflow; });
}

/** Structural validation — safe to call at boot or in CI. */
export function validateWorkflows(list) {
  const items = list || WORKFLOWS;
  const problems = [];
  const seen = {};
  items.forEach(function (w) {
    if (seen[w.id]) problems.push('duplicate id: ' + w.id);
    seen[w.id] = true;
    if (!w.condition) problems.push(w.id + ': missing condition name');
    if (!w.algorithm || !w.algorithm.length) problems.push(w.id + ': empty algorithm');
    if (w.status === 'cited' && (!w.citations || !w.citations.length)) {
      problems.push(w.id + ': marked cited but has no citations');
    }
    (w.citations || []).forEach(function (c) {
      if (!/^https:\/\//.test(c.url || '')) problems.push(w.id + ': citation url not https — ' + c.url);
      if (!c.licence) problems.push(w.id + ': citation missing licence — ' + c.title);
    });
    const nodeIds = {};
    (w.algorithm || []).forEach(function (n) { nodeIds[n.id] = true; });
    (w.algorithm || []).forEach(function (n) {
      (n.next || []).forEach(function (t) {
        if (!nodeIds[t]) problems.push(w.id + ': node ' + n.id + ' points to missing node ' + t);
      });
      (n.branches || []).forEach(function (b) {
        if (!nodeIds[b.to] && !Object.prototype.hasOwnProperty.call(WORKFLOWS_BY_ID, b.to)) {
          problems.push(w.id + ': branch "' + b.label + '" points to unknown target ' + b.to);
        }
      });
    });
  });
  return problems;
}
